script:
$svc = 'wuauserv','bits','cryptsvc','msiserver','UsoSvc'
foreach ($s in $svc) { Stop-Service $s -Force -ErrorAction SilentlyContinue }
$stamp = Get-Date -Format 'yyyyMMddHHmmss'
foreach ($d in "$env:SystemRoot\SoftwareDistribution", "$env:SystemRoot\System32\catroot2") { if (Test-Path $d) { Rename-Item $d "$(Split-Path $d -Leaf).bak$stamp" -ErrorAction SilentlyContinue; "Renamed $d" } }
foreach ($s in 'wuauserv','bits','cryptsvc') { Set-Service $s -StartupType Manual -ErrorAction SilentlyContinue }
Set-Service bits -StartupType AutomaticDelayedStart -ErrorAction SilentlyContinue
foreach ($s in $svc) { Start-Service $s -ErrorAction SilentlyContinue }
'Windows Update has been reset. Check for updates in Settings.'

$ad = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object Status -eq 'Up'
foreach ($a in $ad) { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses @('1.1.1.1','1.0.0.1','2606:4700:4700::1111','2606:4700:4700::1001'); "$($a.Name): DNS set to Cloudflare" }
Clear-DnsClientCache

$ad = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object Status -eq 'Up'
foreach ($a in $ad) { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses @('9.9.9.9','149.112.112.112','2620:fe::fe','2620:fe::9'); "$($a.Name): DNS set to Quad9" }
Clear-DnsClientCache

$ad = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object Status -eq 'Up'
foreach ($a in $ad) { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses @('8.8.8.8','8.8.4.4','2001:4860:4860::8888','2001:4860:4860::8844'); "$($a.Name): DNS set to Google" }
Clear-DnsClientCache

$ad = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object Status -eq 'Up'
foreach ($a in $ad) { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses @('94.140.14.14','94.140.15.15','2a10:50c0::ad1:ff','2a10:50c0::ad2:ff'); "$($a.Name): DNS set to AdGuard" }
Clear-DnsClientCache

$before = 0; $removed = 0
foreach ($d in @($env:TEMP, "$env:SystemRoot\Temp")) {
  Get-ChildItem $d -Recurse -Force -File -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-1) } | ForEach-Object { $before += $_.Length; try { Remove-Item $_.FullName -Force -ErrorAction Stop; $removed += $_.Length } catch { } }
  Get-ChildItem $d -Recurse -Force -Directory -ErrorAction SilentlyContinue | Sort-Object { $_.FullName.Length } -Descending | ForEach-Object { if (-not (Get-ChildItem $_.FullName -Force -ErrorAction SilentlyContinue)) { Remove-Item $_.FullName -Force -ErrorAction SilentlyContinue } }
}
"Freed {0:N1} MB" -f ($removed / 1MB)

$base = ${env:ProgramFiles(x86)}; if (-not $base) { $base = $env:ProgramFiles }
$setup = Get-ChildItem "$base\Microsoft\EdgeWebView\Application\*\Installer\setup.exe" -ErrorAction SilentlyContinue | Sort-Object { try { [version]$_.Directory.Parent.Name } catch { [version]'0.0' } } -Descending | Select-Object -First 1
if ($setup) { $rc = Invoke-RwNative $setup.FullName '--repair --msedgewebview --system-level'; "WebView2 runtime repaired with $($setup.FullName) (exit code $rc). Reopen Rigwright if its window went blank." }
else { $wg = Get-RwWinget; if ($wg) { $rc = Invoke-RwNative $wg 'install --id Microsoft.EdgeWebView2Runtime --exact --silent --accept-package-agreements --accept-source-agreements --disable-interactivity'; "Evergreen WebView2 installer not found - reinstalled the runtime through winget (exit code $rc). Reopen Rigwright if its window went blank." } else { 'WebView2 installer not found and winget is unavailable - install Microsoft Edge WebView2 Runtime from the Apps page.' } }

$n = 0
Get-AppxPackage -AllUsers | Where-Object { $_.InstallLocation -and (Test-Path "$($_.InstallLocation)\AppxManifest.xml") } | ForEach-Object { try { Add-AppxPackage -DisableDevelopmentMode -Register "$($_.InstallLocation)\AppxManifest.xml" -ErrorAction Stop; $n++ } catch { } }
"Re-registered $n packages"
